target.css:
:root {
  --navy: #17324d;
  --navy-deep: #10263a;
  --paper: #fffdf7;
  --cream: #f7f0df;
  --amber: #efad32;
  --gold: #f7cd58;
  --coral: #e7624b;
  --teal: #2c9b91;
  --ink: #203646;
  --muted: #6d7d83;
  --line: #d9dfd8;
  --white: #ffffff;
}

.range-card {
  box-sizing: border-box;
  width: 500px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--navy);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 11px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.kicker {
  margin: 0;
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
  line-height: 1;
}

.session-title {
  margin: 0;
  color: var(--navy);
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -0.4px;
  line-height: 1.15;
}

.live-badge {
  padding: 6px 9px;
  color: var(--white);
  background: var(--coral);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.6px;
  line-height: 1;
}

.main-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 12px;
  padding: 12px 0;
}

.target-panel {
  display: flex;
  flex-direction: column;
  min-height: 151px;
  padding: 10px;
  background: var(--navy-deep);
  border-radius: 12px;
}

.lane-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.lane-label {
  color: var(--gold);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.round-time {
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
}

.target-face {
  position: relative;
  width: 76px;
  height: 76px;
  margin: 4px auto 3px;
  background: var(--amber);
  border: 3px solid var(--cream);
  border-radius: 50%;
}

.ring {
  position: absolute;
  display: block;
  border-radius: 50%;
}

.ring-outer {
  inset: 12px;
  background: var(--coral);
}

.ring-middle {
  inset: 25px;
  background: var(--cream);
}

.ring-core {
  inset: 34px;
  background: var(--teal);
}

.arrow-mark {
  position: absolute;
  top: 26px;
  left: 27px;
  z-index: 1;
  color: var(--navy-deep);
  font-size: 24px;
  font-weight: 900;
  line-height: 1;
  transform: rotate(-42deg);
}

.last-shot {
  margin: auto 0 0;
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  text-align: center;
}

.shot-dot {
  color: var(--gold);
  font-size: 10px;
}

.details-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.score-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}

.score-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 9px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.score-block-accent {
  background: var(--teal);
  border-color: var(--teal);
}

.score-value {
  color: var(--navy);
  font-size: 22px;
  font-weight: 850;
  letter-spacing: -0.6px;
  line-height: 0.95;
}

.score-block-accent .score-value,
.score-block-accent .score-label {
  color: var(--white);
}

.score-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
  line-height: 1;
}

.conditions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.condition {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.1;
}

.condition:last-child {
  grid-column: 1 / -1;
}

.condition-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--teal);
  background: var(--cream);
  border-radius: 5px;
  font-size: 12px;
  font-weight: 900;
}

.score-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: auto;
  padding: 8px 10px;
  color: var(--white);
  background: var(--navy);
  border: 1px solid var(--navy);
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.progress-footer {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 9px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.progress-label,
.progress-count {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.progress-track {
  display: block;
  height: 7px;
  overflow: hidden;
  background: var(--cream);
  border-radius: 999px;
}

.progress-fill {
  display: block;
  width: 83.333%;
  height: 100%;
  background: var(--amber);
  border-radius: 999px;
}
